1	use std::fmt::{self, Debug, Formatter};
2	use std::ops::{Deref, DerefMut};
3	
4	use typst_library::engine::Engine;
5	use typst_library::introspection::{SplitLocator, Tag, TagFlags};
6	use typst_library::layout::{Abs, Dir, Em, Fr, Frame, FrameItem, Point};
7	use typst_library::model::ParLineMarker;
8	use typst_library::text::{Lang, TextElem, families, variant};
9	use typst_utils::Numeric;
10	
11	use super::*;
12	use crate::inline::linebreak::Trim;
13	use crate::inline::shaping::Adjustability;
14	use crate::modifiers::layout_and_modify;
15	
16	const SHY: char = '\u{ad}';
17	const HYPHEN: char = '-';
18	const EN_DASH: char = '–';
19	const EM_DASH: char = '—';
20	const LINE_SEPARATOR: char = '\u{2028}'; // We use LS to distinguish justified breaks.
21	
22	/// A layouted line, consisting of a sequence of layouted inline items that are
23	/// mostly borrowed from the preparation phase. This type enables you to measure
24	/// the size of a line in a range before committing to building the line's
25	/// frame.
26	///
27	/// At most two inline items must be created individually for this line: The
28	/// first and last one since they may be broken apart by the start or end of the
29	/// line, respectively. But even those can partially reuse previous results when
30	/// the break index is safe-to-break per rustybuzz.
31	pub struct Line<'a> {
32	    /// The items the line is made of.
33	    pub items: Items<'a>,
34	    /// The exact natural width of the line.
35	    pub width: Abs,
36	    /// Whether the line should be justified.
37	    pub justify: bool,
38	    /// Whether the line ends with a hyphen or dash, either naturally or through
39	    /// hyphenation.
40	    pub dash: Option<Dash>,
41	}
42	
43	impl Line<'_> {
44	    /// Create an empty line.
45	    pub fn empty() -> Self {
46	        Self {
47	            items: Items::new(),
48	            width: Abs::zero(),
49	            justify: false,
50	            dash: None,
51	        }
52	    }
53	
54	    /// How many glyphs are in the text where we can insert additional
55	    /// space when encountering underfull lines.
56	    pub fn justifiables(&self) -> usize {
57	        let mut count = 0;
58	        for shaped in self.items.iter().filter_map(Item::text) {
59	            count += shaped.justifiables();
60	        }
61	
62	        // CJK character at line end should not be adjusted.
63	        if self
64	            .items
65	            .trailing_text()
66	            .map(|s| s.cjk_justifiable_at_last())
67	            .unwrap_or(false)
68	        {
69	            count -= 1;
70	        }
71	
72	        count
73	    }
74	
75	    /// How much the line can stretch.
76	    pub fn stretchability(&self) -> Abs {
77	        self.items
78	            .iter()
79	            .filter_map(Item::text)
80	            .map(|s| s.stretchability())
81	            .sum()
82	    }
83	
84	    /// How much the line can shrink.
85	    pub fn shrinkability(&self) -> Abs {
86	        self.items
87	            .iter()
88	            .filter_map(Item::text)
89	            .map(|s| s.shrinkability())
90	            .sum()
91	    }
92	
93	    /// Whether the line has items with negative width.
94	    pub fn has_negative_width_items(&self) -> bool {
95	        self.items.iter().any(|item| match item {
96	            Item::Absolute(amount, _) => *amount < Abs::zero(),
97	            Item::Frame(frame) => frame.width() < Abs::zero(),
98	            _ => false,
99	        })
100	    }
101	
102	    /// The sum of fractions in the line.
103	    pub fn fr(&self) -> Fr {
104	        self.items
105	            .iter()
106	            .filter_map(|item| match item {
107	                Item::Fractional(fr, _) => Some(*fr),
108	                _ => None,
109	            })
110	            .sum()
111	    }
112	}
113	
114	/// A dash at the end of a line.
115	#[derive(Debug, Copy, Clone, Eq, PartialEq)]
116	pub enum Dash {
117	    /// A soft hyphen added to break a word.
118	    Soft,
119	    /// A regular hyphen, present in a compound word, e.g. beija-flor.
120	    Hard,
121	    /// Another kind of dash. Only relevant for cost computation.
122	    Other,
123	}
124	
125	/// Create a line which spans the given range.
126	pub fn line<'a>(
127	    engine: &Engine,
128	    p: &'a Preparation,
129	    range: Range,
130	    breakpoint: Breakpoint,
131	    pred: Option<&Line<'a>>,
132	) -> Line<'a> {
133	    // The line's full text.
134	    let full = &p.text[range.clone()];
135	
136	    // Whether the line is justified.
137	    let justify = full.ends_with(LINE_SEPARATOR)
138	        || (p.config.justify && breakpoint != Breakpoint::Mandatory);
139	
140	    // Process dashes.
141	    let dash = if breakpoint.is_hyphen() || full.ends_with(SHY) {
142	        Some(Dash::Soft)
143	    } else if full.ends_with(HYPHEN) {
144	        Some(Dash::Hard)
145	    } else if full.ends_with([EN_DASH, EM_DASH]) {
146	        Some(Dash::Other)
147	    } else {
148	        None
149	    };
150	
151	    // Trim the line at the end, if necessary for this breakpoint.
152	    let trim = breakpoint.trim(range.start, full);
153	    let trimmed_range = range.start..trim.layout;
154	
155	    // Collect the items for the line.
156	    let mut items = Items::new();
157	
158	    // Add a hyphen at the line start, if a previous dash should be repeated.
159	    if let Some(pred) = pred
160	        && pred.dash == Some(Dash::Hard)
161	        && let Some(base) = pred.items.trailing_text()
162	        && should_repeat_hyphen(base.lang, full)
163	        && let Some(hyphen) =
164	            ShapedText::hyphen(engine, p.config.fallback, base, trim.shaping, false)
165	    {
166	        items.push(Item::Text(hyphen), LogicalIndex::START_HYPHEN);
167	    }
168	
169	    collect_items(&mut items, engine, p, range, &trim);
170	
171	    // Add a hyphen at the line end, if we ended on a soft hyphen.
172	    if dash == Some(Dash::Soft)
173	        && let Some(base) = items.trailing_text()
174	        && let Some(hyphen) =
175	            ShapedText::hyphen(engine, p.config.fallback, base, trim.shaping, true)
176	    {
177	        items.push(Item::Text(hyphen), LogicalIndex::END_HYPHEN);
178	    }
179	
180	    // Ensure that there is no weak spacing at the start and end of the line.
181	    trim_weak_spacing(&mut items);
182	
183	    // Deal with CJ characters at line boundaries.
184	    // Use the trimmed range for robust boundary checks.
185	    adjust_cj_at_line_boundaries(p, trimmed_range, &mut items);
186	
187	    // Deal with stretchability of glyphs at the end of the line.
188	    adjust_glyph_stretch_at_line_end(p, &mut items);
189	
190	    // Compute the line's width.
191	    let width = items.iter().map(Item::natural_width).sum();
192	
193	    Line { items, width, justify, dash }
194	}
195	
196	/// Collects / reshapes all items for the line with the given `range`.
197	///
198	/// The `trim` defines an end position to which text items are trimmed. For
199	/// example, the `range` may span "hello\n", but the `trim` specifies that the
200	/// linebreak is trimmed.
201	///
202	/// We do not factor the `trim` directly into the `range` because we still want
203	/// to keep non-text items after the trim (e.g. tags).
204	fn collect_items<'a>(
205	    items: &mut Items<'a>,
206	    engine: &Engine,
207	    p: &'a Preparation,
208	    range: Range,
209	    trim: &Trim,
210	) {
211	    let mut fallback = None;
212	
213	    // Collect the items for each consecutively ordered run.
214	    reorder(p, range.clone(), |subrange, rtl| {
215	        let from = items.len();
216	        collect_range(engine, p, subrange, trim, items, &mut fallback);
217	        if rtl {
218	            items.reorder(from);
219	        }
220	    });
221	
222	    // Add fallback text to expand the line height, if necessary.
223	    if !items.iter().any(|item| matches!(item, Item::Text(_)))
224	        && let Some((idx, fallback)) = fallback
225	    {
226	        items.push(fallback, idx);
227	    }
228	}
229	
230	/// Trims weak spacing from the start and end of the line.
231	fn trim_weak_spacing(items: &mut Items) {
232	    // Trim weak spacing at the start of the line.
233	    let prefix = items
234	        .iter()
235	        .take_while(|item| matches!(item, Item::Absolute(_, true)))
236	        .count();
237	    if prefix > 0 {
238	        items.drain(..prefix);
239	    }
240	
241	    // Trim weak spacing at the end of the line.
242	    while matches!(items.iter().next_back(), Some(Item::Absolute(_, true))) {
243	        items.pop();
244	    }
245	}
