247	/// Calls `f` for the BiDi-reordered ranges of a line.
248	fn reorder<F>(p: &Preparation, range: Range, mut f: F)
249	where
250	    F: FnMut(Range, bool),
251	{
252	    // If there is nothing bidirectional going on, skip reordering.
253	    let Some(bidi) = &p.bidi else {
254	        f(range, p.config.dir == Dir::RTL);
255	        return;
256	    };
257	
258	    // The bidi crate panics for empty lines.
259	    if range.is_empty() {
260	        f(range, p.config.dir == Dir::RTL);
261	        return;
262	    }
263	
264	    // Find the paragraph that contains the line.
265	    let para = bidi
266	        .paragraphs
267	        .iter()
268	        .find(|para| para.range.contains(&range.start))
269	        .unwrap();
270	
271	    // Compute the reordered ranges in visual order (left to right).
272	    let (levels, runs) = bidi.visual_runs(para, range.clone());
273	
274	    // Call `f` for each run.
275	    for run in runs {
276	        let rtl = levels[run.start].is_rtl();
277	        f(run, rtl);
278	    }
279	}
