281	/// Collects / reshapes all items for the given `subrange` with continuous
282	/// direction.
283	fn collect_range<'a>(
284	    engine: &Engine,
285	    p: &'a Preparation,
286	    range: Range,
287	    trim: &Trim,
288	    items: &mut Items<'a>,
289	    fallback: &mut Option<(LogicalIndex, ItemEntry<'a>)>,
290	) {
291	    for (i, (subrange, item)) in p.slice(range.clone()) {
292	        let idx = LogicalIndex::from_item_index(i);
293	
294	        // All non-text items are just kept, they can't be split.
295	        let Item::Text(shaped) = item else {
296	            items.push(item, idx);
297	            continue;
298	        };
299	
300	        // The intersection range of the item, the subrange, and the line's
301	        // trimming.
302	        let sliced = range.start.max(subrange.start)
303	            ..range.end.min(subrange.end).min(trim.shaping);
304	
305	        // Whether the item is split by the line.
306	        let split = subrange.start < sliced.start || sliced.end < subrange.end;
307	
308	        if sliced.is_empty() {
309	            // When there is no text, still keep this as a fallback item, which
310	            // we can use to force a non-zero line-height when the line doesn't
311	            // contain any other text.
312	            *fallback = Some((idx, ItemEntry::from(Item::Text(shaped.empty()))));
313	            continue;
314	        }
315	
316	        let mut item: ItemEntry = if split {
317	            // When the item is split in half, reshape it.
318	            let reshaped = shaped.reshape(engine, sliced);
319	            Item::Text(reshaped).into()
320	        } else {
321	            // When the item is fully contained, just keep it.
322	            item.into()
323	        };
324	
325	        // Trim end-of-line whitespace glyphs.
326	        if trim.layout < range.end {
327	            let shaped = item.text_mut().unwrap();
328	            // Make sure not to trim glyphs that have overlapping ranges, for
329	            // example due to zero width spaces included in the cluster.
330	            // Otherwise these glyphs would protrude into the margin.
331	            shaped.glyphs.trim(|glyph| glyph.range.start >= trim.layout);
332	        }
333	
334	        items.push(item, idx);
335	    }
336	}
