338	/// Add spacing around punctuation marks for CJ glyphs at line boundaries.
339	///
340	/// See Requirements for Chinese Text Layout, Section 3.1.6.3 Compression of
341	/// punctuation marks at line start or line end.
342	///
343	/// The `range` should only contain regular texts, with linebreaks trimmed.
344	fn adjust_cj_at_line_boundaries(p: &Preparation, range: Range, items: &mut Items) {
345	    let text = &p.text[range];
346	
347	    if text.starts_with(BEGIN_PUNCT_PAT)
348	        || (p.config.cjk_latin_spacing && text.starts_with(is_of_cj_script))
349	    {
350	        adjust_cj_at_line_start(p, items);
351	    }
352	
353	    if text.ends_with(END_PUNCT_PAT)
354	        || (p.config.cjk_latin_spacing && text.ends_with(is_of_cj_script))
355	    {
356	        adjust_cj_at_line_end(p, items);
357	    }
358	}
