456	/// Apply the current baseline shift and italic compensation to a frame.
457	pub fn apply_shift<'a>(
458	    world: &Tracked<'a, dyn World + 'a>,
459	    frame: &mut Frame,
460	    styles: StyleChain,
461	) {
462	    let mut baseline = styles.resolve(TextElem::baseline);
463	    let mut compensation = Abs::zero();
464	    if let Some(scripts) = styles.get_ref(TextElem::shift_settings) {
465	        let variant = variant(styles);
466	        let size = styles.resolve(TextElem::size);
467	        let variations = styles.get_cloned(TextElem::variations);
468	        let font_metrics = families(styles)
469	            .find_map(|family| {
470	                world
471	                    .book()
472	                    .select(family.as_str(), variant)
473	                    .and_then(|id| world.font(id))
474	                    .map(|font| font.instantiate(variant, size, &variations))
475	            })
476	            .map_or(*scripts.kind.default_metrics(), |f| {
477	                *scripts.kind.read_metrics(f.metrics())
478	            });
479	        baseline -= scripts.shift.unwrap_or(font_metrics.vertical_offset).at(size);
480	        compensation += font_metrics.horizontal_offset.at(size);
481	    }
482	    frame.translate(Point::new(compensation, baseline));
483	}
