637	/// Adds a paragraph line marker to a paragraph line's output frame if
638	/// line numbering is not `None` at this point. Ensures other style properties,
639	/// namely number margin, number align and number clearance, are stored in the
640	/// marker as well.
641	///
642	/// The `top` parameter is used to ensure the marker, and thus the line's
643	/// number in the margin, is aligned to the line's baseline.
644	fn add_par_line_marker(
645	    output: &mut Frame,
646	    marker: &Packed<ParLineMarker>,
647	    engine: &mut Engine,
648	    locator: &mut SplitLocator,
649	    top: Abs,
650	) {
651	    // Elements in tags must have a location for introspection to work. We do
652	    // the work here instead of going through all of the realization process
653	    // just for this, given we don't need to actually place the marker as we
654	    // manually search for it in the frame later (when building a root flow,
655	    // where line numbers can be displayed), so we just need it to be in a tag
656	    // and to be valid (to have a location).
657	    let mut marker = marker.clone();
658	    let key = typst_utils::hash128(&marker);
659	    let loc = locator.next_location(engine, key, marker.span());
660	    marker.set_location(loc);
661	
662	    // Create start and end tags through which we can search for this line's
663	    // marker later. The 'x' coordinate is not important, just the 'y'
664	    // coordinate, as that's what is used for line numbers. We will place the
665	    // tags among other subframes in the line such that it is aligned with the
666	    // line's general baseline. However, the line number will still need to
667	    // manually adjust its own 'y' position based on its own baseline.
668	    let pos = Point::with_y(top);
669	    let flags = TagFlags { introspectable: false, tagged: false };
670	    output.push(pos, FrameItem::Tag(Tag::Start(marker.pack(), flags)));
671	    output.push(pos, FrameItem::Tag(Tag::End(loc, key, flags)));
672	}
