771	/// We use indices to remember the logical (as opposed to visual) order of
772	/// items. During line building, the items are stored in visual (BiDi-reordered)
773	/// order. When committing to a line and building its frame, we sort by logical
774	/// index.
775	///
776	/// - Special layout-generated items have custom indices that ensure correct
777	///   ordering w.r.t. to each other and normal elements, listed below.
778	/// - Normal items have their position in `p.items` plus the number of special
779	///   reserved prefix indices.
780	///
781	/// Logical indices must be unique within a line because we use an unstable
782	/// sort.
783	#[derive(Debug, Copy, Clone, Eq, PartialEq, Ord, PartialOrd)]
784	pub struct LogicalIndex(usize);
785	
786	impl LogicalIndex {
787	    const START_HYPHEN: Self = Self(0);
788	    const END_HYPHEN: Self = Self(usize::MAX);
789	
790	    /// Create a logical index from the index of an item in the [`p.items`](Preparation::items).
791	    const fn from_item_index(i: usize) -> Self {
792	        // This won't overflow because the `idx` comes from a vector which is
793	        // limited to `isize::MAX` elements.
794	        Self(i + 1)
795	    }
796	}
797	
798	/// A reference to or a boxed item.
799	///
800	/// This is conceptually similar to a [`Cow<'a, Item<'a>>`][std::borrow::Cow],
801	/// but we box owned items since an [`Item`] is much bigger than
802	/// a box.
803	pub enum ItemEntry<'a> {
804	    Ref(&'a Item<'a>),
805	    Box(Box<Item<'a>>),
806	}
807	
808	impl<'a> ItemEntry<'a> {
809	    fn text_mut(&mut self) -> Option<&mut ShapedText<'a>> {
810	        match self {
811	            Self::Ref(item) => {
812	                let text = item.text()?;
813	                *self = Self::Box(Box::new(Item::Text(text.clone())));
814	                match self {
815	                    Self::Box(item) => item.text_mut(),
816	                    Self::Ref(_) => unreachable!(),
817	                }
818	            }
819	            Self::Box(item) => item.text_mut(),
820	        }
821	    }
822	}
823	
824	impl<'a> Deref for ItemEntry<'a> {
825	    type Target = Item<'a>;
826	
827	    fn deref(&self) -> &Self::Target {
828	        match self {
829	            Self::Ref(item) => item,
830	            Self::Box(item) => item,
831	        }
832	    }
833	}
834	
835	impl Debug for ItemEntry<'_> {
836	    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
837	        (**self).fmt(f)
838	    }
839	}
840	
841	impl<'a> From<&'a Item<'a>> for ItemEntry<'a> {
842	    fn from(item: &'a Item<'a>) -> Self {
843	        Self::Ref(item)
844	    }
845	}
846	
847	impl<'a> From<Item<'a>> for ItemEntry<'a> {
848	    fn from(item: Item<'a>) -> Self {
849	        Self::Box(Box::new(item))
850	    }
851	}
